import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as r,af as a}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Cloud Agents","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/cursor/cloud-agents.md","filePath":"products/ai-coding/cursor/cloud-agents.md","lastUpdated":1787107158000}'),n={name:"products/ai-coding/cursor/cloud-agents.md"};function s(i,t,d,l,c,u){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="cloud-agents" tabindex="-1">Cloud Agents <a class="header-anchor" href="#cloud-agents" aria-label="Permalink to &quot;Cloud Agents&quot;">​</a></h1><p>Cloud Agents use the same <a href="https://cursor.com/learn/agents" target="_blank" rel="noreferrer">agent fundamentals</a> but run in <strong>isolated VMs</strong> with a full development environment: cloned repos, installed dependencies, secrets, startup commands, and network access.</p><blockquote><p>Official: <a href="https://cursor.com/docs/cloud-agent" target="_blank" rel="noreferrer">Cloud Agents</a>. <strong>Former name: Background Agents</strong> — one product, not two.</p><p>This page is the <strong>form</strong>: when to use it, how to start it, what differs from local. Task recipes stay in the <a href="./cursor-cookbook.html#run-work-on-cloud-agents">cookbook</a>.</p></blockquote><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A <strong>paid</strong> Cursor plan</li><li>An account <strong>admin</strong> has connected source control: <a href="https://cursor.com/docs/integrations/github" target="_blank" rel="noreferrer">GitHub</a>, <a href="https://cursor.com/docs/integrations/gitlab" target="_blank" rel="noreferrer">GitLab</a>, <a href="https://cursor.com/docs/integrations/bitbucket" target="_blank" rel="noreferrer">Bitbucket Cloud</a>, or <a href="https://cursor.com/docs/integrations/azure-devops" target="_blank" rel="noreferrer">Azure DevOps</a></li><li>Read-write access to the repo (and any dependent repos or submodules)</li><li>You accept that Cloud is officially the feature that requires Cursor to <strong>store code</strong>. If policy forbids storage, leave Cloud off</li></ul><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>After this page you can:</p><ol><li>Decide Cloud vs local Agent vs Bugbot vs CLI</li><li>Start a run from desktop, web, mobile / PWA, Slack, GitHub, Linear, or <code>agent</code> + <code>&amp;</code></li><li>Treat <strong>environment setup</strong> as the main lever</li><li>Know the official MCP / Hooks limits on the VM</li></ol><hr><h2 id="why-use-cloud-agents" tabindex="-1">Why use Cloud Agents <a class="header-anchor" href="#why-use-cloud-agents" aria-label="Permalink to &quot;Why use Cloud Agents&quot;">​</a></h2><ul><li>Run <strong>as many agents as you want in parallel</strong></li><li>Your laptop does <strong>not</strong> need to stay online</li><li>The VM can <strong>build, test, and interact</strong> with the changed software, including desktop / browser computer use</li><li>Team <a href="https://cursor.com/docs/mcp" target="_blank" rel="noreferrer">MCP servers</a> (HTTP and stdio; OAuth when the server needs it)</li><li><strong>Multi-repo</strong> environments: inspect the workspace, make coordinated changes, open a PR <strong>per repo it changes</strong>. Official: <strong>long-running is not available for multi-repo yet</strong></li></ul><p>Official wording: skipping environment setup is like not giving engineers a computer.</p><h2 id="how-to-start-one" tabindex="-1">How to start one <a class="header-anchor" href="#how-to-start-one" aria-label="Permalink to &quot;How to start one&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>How</th></tr></thead><tbody><tr><td><strong>Cursor Desktop</strong></td><td>Agent input → <strong>Cloud</strong> in the dropdown</td></tr><tr><td><strong>Cursor Web</strong></td><td><a href="https://cursor.com/agents" target="_blank" rel="noreferrer">cursor.com/agents</a> on any device</td></tr><tr><td><strong>Cursor for iOS</strong></td><td>Native app — <a href="https://cursor.com/docs/cloud-agent/mobile" target="_blank" rel="noreferrer">mobile</a></td></tr><tr><td><strong>Android</strong></td><td>Chrome → <a href="https://cursor.com/agents" target="_blank" rel="noreferrer">cursor.com/agents</a> → <strong>Install App</strong> (PWA)</td></tr><tr><td><strong>Slack / Linear</strong></td><td><code>@cursor</code> (admin installs the app first)</td></tr><tr><td><strong>GitHub / Bitbucket</strong></td><td>Comment <code>@cursor</code> on a PR or (GitHub) issue</td></tr><tr><td><strong>API</strong></td><td>Cloud Agents API</td></tr><tr><td><strong>Cursor CLI</strong></td><td>Prefix a message with <code>&amp;</code> — see <a href="./cursor-cli.html">CLI</a></td></tr></tbody></table><p>Do <strong>not</strong> send “three lines under the caret” here — that is Tab. Do <strong>not</strong> use Cloud as a PR reviewer — that is <a href="./cursor-cookbook.html#review-prs-with-bugbot">Bugbot</a>.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li>Cloud clones from the connected provider onto a <strong>separate branch</strong></li><li>The agent works in the configured environment</li><li>It pushes and hands off (often a merge-ready PR plus artifacts)</li></ol><p>Configure the environment with agent-led setup, a saved snapshot, or a Dockerfile via <code>.cursor/environment.json</code>. See <a href="https://cursor.com/docs/cloud-agent/setup" target="_blank" rel="noreferrer">Cloud agent setup</a>. <a href="https://cursor.com/docs/cloud-agent/builds" target="_blank" rel="noreferrer">Builds</a> prepare repos and dependencies in the background.</p><p>Hover the repository name on an agent page to see which environment and Build that run used.</p><p>Runtime controls (official): secrets, outbound domain allowlists, Tailscale / similar for private networks, private connectivity for supported SCM paths. Full set: <a href="https://cursor.com/docs/cloud-agent/security-network" target="_blank" rel="noreferrer">Security and network</a>.</p><h2 id="mcp-and-hooks-official-limits" tabindex="-1">MCP and Hooks (official limits) <a class="header-anchor" href="#mcp-and-hooks-official-limits" aria-label="Permalink to &quot;MCP and Hooks (official limits)&quot;">​</a></h2><p><strong>MCP:</strong> team servers from the MCP dropdown on <a href="https://cursor.com/agents" target="_blank" rel="noreferrer">cursor.com/agents</a>. HTTP and stdio. OAuth supported. Built-in <a href="https://cursor.com/docs/cloud-agent/capabilities.md#cursor-cloud-mcp" target="_blank" rel="noreferrer">Cursor Cloud MCP</a> for run diagnostics (transcripts, events, environment, setup logs).</p><p><strong>Hooks:</strong> command-based hooks from <strong><code>.cursor/hooks.json</code> in the repo</strong>. Enterprise also runs team hooks and enterprise-managed hooks. They do <strong>not</strong> run during early read-only exploratory turns; they start once the agent has a writable environment.</p><p>Not available on Cloud:</p><ul><li>User-level <code>~/.cursor/hooks.json</code> (the VM has no access to your home directory)</li><li>IDE-specific hooks (Tab hooks, <code>workspaceOpen</code>)</li></ul><p>Supported families include tool / file hooks (<code>preToolUse</code>, <code>beforeShellExecution</code>, <code>afterFileEdit</code>) and lifecycle hooks (<code>beforeSubmitPrompt</code>, <code>subagentStart</code> / <code>subagentStop</code>, <code>preCompact</code>, <code>afterAgentResponse</code> / <code>afterAgentThought</code>, <code>stop</code>). Matrix: <a href="https://cursor.com/docs/hooks.md#cloud-agent-support" target="_blank" rel="noreferrer">Hooks · Cloud agent support</a>.</p><h2 id="artifacts-desktop-and-sharing" tabindex="-1">Artifacts, desktop, and sharing <a class="header-anchor" href="#artifacts-desktop-and-sharing" aria-label="Permalink to &quot;Artifacts, desktop, and sharing&quot;">​</a></h2><ul><li><strong>Artifacts:</strong> screenshots, videos, logs — what changed and how the agent verified it</li><li><strong>Remote desktop:</strong> take control of the agent&#39;s desktop to test without checking out the branch; release control so it continues</li><li><strong>Share:</strong> send the agent URL. Viewers must be on the <strong>same Cursor team</strong> and must connect their <strong>own</strong> SCM account with access to that repo. Team membership alone is not enough. Viewing is read-only unless a team admin enables <a href="https://cursor.com/docs/cloud-agent/settings.md#team-follow-ups" target="_blank" rel="noreferrer">team follow-ups</a></li></ul><h2 id="models-and-billing" tabindex="-1">Models and billing <a class="header-anchor" href="#models-and-billing" aria-label="Permalink to &quot;Models and billing&quot;">​</a></h2><p>Cloud Agents use a curated model list. You can select context-window size on supported models. Larger windows can increase tokens and cost.</p><p>Charged at <strong>API pricing</strong> for the selected <a href="https://cursor.com/docs/models-and-pricing.md#model-pricing" target="_blank" rel="noreferrer">model</a>. You set a spend limit the first time you use them.</p><h2 id="mobile-jetbrains-plugins-automations" tabindex="-1">Mobile, JetBrains, Plugins, Automations <a class="header-anchor" href="#mobile-jetbrains-plugins-automations" aria-label="Permalink to &quot;Mobile, JetBrains, Plugins, Automations&quot;">​</a></h2><p>Index-level only — official pages, not extra tutorials:</p><table tabindex="0"><thead><tr><th>Surface</th><th>Official one-liner</th></tr></thead><tbody><tr><td><strong>iOS / PWA</strong></td><td>Native iOS app (beta, iOS / iPadOS 26+) starts and reviews Cloud Agents. Android: install the PWA. <a href="https://cursor.com/docs/cloud-agent/mobile" target="_blank" rel="noreferrer">Mobile</a></td></tr><tr><td><strong>JetBrains</strong></td><td>ACP agent inside IntelliJ / PyCharm / WebStorm. Paid plan + AI Assistant 2025.1+. <a href="https://cursor.com/docs/integrations/jetbrains" target="_blank" rel="noreferrer">JetBrains</a></td></tr><tr><td><strong>Xcode</strong></td><td>Xcode 26.3+ built-in MCP: build, test, SwiftUI previews, Apple docs. <a href="https://cursor.com/docs/integrations/xcode" target="_blank" rel="noreferrer">Xcode</a></td></tr><tr><td><strong>Plugins</strong></td><td>Bundles of rules, skills, agents, commands, MCP, hooks. <a href="https://cursor.com/docs/plugins" target="_blank" rel="noreferrer">Plugins</a></td></tr><tr><td><strong>Automations</strong></td><td>Cloud Agents on a schedule or events (GitHub, GitLab, Slack, webhooks, Linear, …). Bugbot, Security Agents, and PR Routing are the three Cursor-managed agents on that page. <a href="https://cursor.com/docs/cloud-agent/automations" target="_blank" rel="noreferrer">Automations</a></td></tr></tbody></table><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Cloud</th><th>Stay local</th></tr></thead><tbody><tr><td>Away, overnight, many parallel runs</td><td>You must watch the diff, edit a plan, or use Debug Mode</td></tr><tr><td>Isolated VM + tests + PR</td><td>Secrets / services that never left your machine</td></tr><tr><td>Coordinated multi-repo PRs</td><td>One repo you already have checked out</td></tr></tbody></table><p>Task recipes (environment.json, AGENTS.md heading, dispatch checklist): <a href="./cursor-cookbook.html#run-work-on-cloud-agents">Cookbook · Cloud</a>.</p><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pitfall</th><th>Do this</th></tr></thead><tbody><tr><td>Skip environment setup</td><td>Agent-led setup or <code>.cursor/environment.json</code> + Secrets tab</td></tr><tr><td>Expect local <code>mcp.json</code> / <code>~/.cursor/hooks.json</code></td><td>Team MCP on cursor.com/agents; <strong>project</strong> command hooks only</td></tr><tr><td>Use Cloud as the PR reviewer</td><td><a href="./cursor-cookbook.html#review-prs-with-bugbot">Bugbot</a></td></tr><tr><td>Spin a VM for three lines</td><td>Tab or <code>Cmd+K</code></td></tr><tr><td>Multi-repo <strong>long-running</strong></td><td>Official: <strong>not available yet</strong></td></tr><tr><td>Teammate cannot open your run</td><td>Same team <strong>and</strong> their own SCM access to that repo</td></tr><tr><td>Put <code>.env.local</code> in a snapshot and call it done</td><td>Official preference: <strong>Secrets</strong> tab</td></tr><tr><td>Document “Background Agents” as a second product</td><td>Same product; new name is Cloud Agents</td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./cursor-cookbook.html#run-work-on-cloud-agents">Cookbook · Cloud</a> — recipes</li><li><a href="./cursor-cli.html">Cursor CLI</a> — <code>&amp;</code> handoff from a terminal</li><li><a href="./security-agents.html">Security Agents</a> / <a href="./pr-routing.html">PR Routing</a> — Automations that run on Cloud</li><li><a href="./origin.html">Origin</a> — Cloud can work against Origin remotes</li><li>Official: <a href="https://cursor.com/docs/cloud-agent" target="_blank" rel="noreferrer">Overview</a>, <a href="https://cursor.com/docs/cloud-agent/setup" target="_blank" rel="noreferrer">Setup</a>, <a href="https://cursor.com/docs/cloud-agent/capabilities" target="_blank" rel="noreferrer">Capabilities</a>, <a href="https://cursor.com/docs/cloud-agent/security-network" target="_blank" rel="noreferrer">Security</a></li></ul>',41)])])}const b=e(n,[["render",s]]);export{f as __pageData,b as default};
